{
  "items": [
    {
      "name": "Module.DualBases.lc",
      "module_name": "Mathlib.LinearAlgebra.Dual.Basis",
      "kind": "definition",
      "type": "{R : Type u_1} →\n  {M : Type u_2} →\n    [inst : CommSemiring R] → [inst_1 : AddCommMonoid M] → [Module R M] → {ι : Type u_4} → (ι → M) → (ι →₀ R) → M"
    },
    {
      "name": "Finsupp.linearCombination_onFinset",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} (R : Type u_5) [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  {s : Finset α} {f : α → R} (g : α → M) (hf : ∀ (a : α), f a ≠ 0 → a ∈ s),\n  (Finsupp.linearCombination R g) (Finsupp.onFinset s f hf) = ∑ x ∈ s, f x • g x"
    },
    {
      "name": "Finsupp.linearCombination",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "definition",
      "type": "{α : Type u_1} →\n  {M : Type u_2} →\n    (R : Type u_5) →\n      [inst : Semiring R] → [inst_1 : AddCommMonoid M] → [inst_2 : Module R M] → (α → M) → (α →₀ R) →ₗ[R] M"
    },
    {
      "name": "Finsupp.linearCombination_apply",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} (R : Type u_5) [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  {v : α → M} (l : α →₀ R), (Finsupp.linearCombination R v) l = l.sum fun i a => a • v i"
    },
    {
      "name": "Finsupp.linearCombination_apply_of_mem_supported",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.LinearCombination",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_2} (R : Type u_5) [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M]\n  {v : α → M} {l : α →₀ R} {s : Finset α},\n  l ∈ Finsupp.supported R R ↑s → (Finsupp.linearCombination R v) l = ∑ i ∈ s, l i • v i"
    }
  ]
}
